def assess_late_fee_C2(ws_late_payment_fee: Decimal, ws_total_fees: Decimal) -> Decimal:
    """
    Adds a late payment fee to the total fees
    This function takes the late payment fee and adds it to the total fees
    accumulated for an account or loan. It assumes that both input values
    are non-negative and represents monetary values
    Args:
        ws_late_payment_fee: The amount of the late payment fee to be added. Must be >= 0
        ws_total_fees: The current total fees. Must be >= 0
    Returns:
        Decimal: The updated total fees after adding the late payment fee
    Raises:
        ValueError: If ws_late_payment_fee is negative
        ValueError: If ws_total_fees is negative
    """
    logger.info("Assessing late fee.")
    
    # Validate inputs
    if ws_late_payment_fee < Decimal('0'):
        logger.error(f"Invalid late payment fee: {ws_late_payment_fee}")
        raise ValueError("Late payment fee cannot be negative.")
        
    if ws_total_fees < Decimal('0'):
        logger.error(f"Invalid total fees: {ws_total_fees}")
        raise ValueError("Total fees cannot be negative.")
        
    try:
        # Add the late payment fee to the total fees
        new_total_fees = ws_total_fees + ws_late_payment_fee
        logger.debug(f"Late fee added. New total fees: {new_total_fees}")
        return new_total_fees
    except Exception as e:
        logger.error(f"Failed to assess late fee: {e}")
        raise

