def calculate_premiums_C2() -> None:
    """
    Calculates insurance premiums for all policies
    This function iterates through the insurance master file, reads each
    policy record, and calculates the premium based on factors such as
    coverage amount, risk assessment, and policy type. It calls other
    functions to determine the base premium, apply risk factors, and
    calculate the final premium
    """
    logger.info("Calculating insurance premiums...")
    try:
        ws_eof = False # Initialize ws_eof
        while not ws_eof:
            try:
                insurance_record = read_insurance_master_next_C2() # Read insurance master record
                determine_base_premium_C2(insurance_record)
                apply_risk_factor_C2()
                calculate_final_premium_C2(insurance_record)
            except EOFError:
                ws_eof = True # Set ws_eof to TRUE when end of file is reached
            except Exception as e:
                logger.error(f"Error processing insurance record: {e}")
                raise
    except Exception as e:
        logger.error(f"Error during premium calculation: {e}")
        raise

