def calculate_position_value_C2(investment_record: dict) -> None:
    """
    Calculates the market value of an investment position
    This function multiplies the quantity of the investment by the current
    market price to determine the total market value of the position. The
    result is stored back into the investment record
    Args:
        investment_record: A dictionary containing the investment record data
            It should include the inv_quantity and inv_current_price
    Raises:
        ValueError: If the investment record does not have the expected keys
    """
    logger.info("Calculating position value...")
    try:
        inv_quantity = investment_record.get("inv_quantity")
        inv_current_price = investment_record.get("inv_current_price")

        if inv_quantity is None or inv_current_price is None:
            logger.error("Missing quantity or current price in investment record.")
            raise ValueError("Investment record missing required quantity or current price.")

        inv_market_value = inv_quantity * inv_current_price
        investment_record["inv_market_value"] = inv_market_value
        logger.debug(f"Market value calculated: {inv_market_value}")

    except KeyError as e:
        logger.error(f"Missing key in investment record: {e}")
        raise ValueError(f"Investment record missing required key: {e}")
    except Exception as e:
        logger.error(f"Error calculating position value: {e}")
        raise

def calculate_gain_loss_C2(investment_record: dict) -> None:
    """
    Calculates the gain or loss on an investment position
    This function subtracts the original purchase value of the investment
    from the current market value to determine the gain or loss. The
    result is stored back into the investment record
    Args:
        investment_record: A dictionary containing the investment record data
            It should include the inv_market_value, inv_quantity, and
            inv_purchase_price
    Raises:
        ValueError: If the investment record does not have the expected keys
    """
    logger.info("Calculating gain/loss...")
    try:
        inv_market_value = investment_record.get("inv_market_value")
        inv_quantity = investment_record.get("inv_quantity")
        inv_purchase_price = investment_record.get("inv_purchase_price")

        if inv_market_value is None or inv_quantity is None or inv_purchase_price is None:
            logger.error("Missing market value, quantity, or purchase price in investment record.")
            raise ValueError("Investment record missing required market value, quantity, or purchase price.")

        inv_gain_loss = inv_market_value - (inv_quantity * inv_purchase_price)
        investment_record["inv_gain_loss"] = inv_gain_loss
        logger.debug(f"Gain/loss calculated: {inv_gain_loss}")

    except KeyError as e:
        logger.error(f"Missing key in investment record: {e}")
        raise ValueError(f"Investment record missing required key: {e}")
    except Exception as e:
        logger.error(f"Error calculating gain/loss: {e}")
        raise

def update_totals_C2(investment_record: dict) -> None:
    """
    Updates the total investment value
    This function adds the market value of the current investment position
    to the running total of all investments
    """
    logger.info("Updating totals...")
    try:
        inv_market_value = investment_record.get("inv_market_value")

        if inv_market_value is None:
            logger.error("Missing market value in investment record.")
            raise ValueError("Investment record missing required market value.")

        global ws_total_investments  # Assume this is an outside variable
        ws_total_investments += inv_market_value
        logger.debug(f"Total investments updated: {ws_total_investments}")

    except Exception as e:
        logger.error(f"Error updating totals: {e}")
        raise

