def transaction_limits_C3(ws_calc_amount: Decimal, ws_not_approved: bool) -> bool:
    """
    Enforces transaction limits for online banking
    This function enforces transaction limits for online banking,
    preventing users from exceeding pre-defined spending limits
    Args:
        ws_calc_amount: The amount of the transaction
        ws_not_approved: Flag indicating if the transaction is not approved
    Returns:
        bool: The updated value of ws_not_approved
    """
    logger.info("Entering transaction_limits_C3")
    try:
        # Validate inputs
        if not isinstance(ws_calc_amount, Decimal):
            logger.error(f"Invalid ws_calc_amount type: {type(ws_calc_amount)}")
            raise ValueError("ws_calc_amount must be a Decimal.")

        if not isinstance(ws_not_approved, bool):
            logger.error(f"Invalid ws_not_approved type: {type(ws_not_approved)}")
            raise ValueError("ws_not_approved must be a bool.")

        if ws_calc_amount > Decimal('5000'):
            ws_not_approved = True
            logger.debug("Transaction not approved due to limit exceeded")
        else:
            logger.debug("Transaction approved")

        return ws_not_approved

    except Exception as e:
        logger.error(f"Error enforcing transaction limits: {e}")
        raise

