        if not isinstance(ws_total_fees, Decimal):
            logger.error(f"Invalid ws_total_fees type: {type(ws_total_fees)}")
            raise ValueError("ws_total_fees must be a Decimal.")

        display_message = "PROCESSING P2P TRANSFERS..."
