def b110_capital_ratios_C4(ws_total_deposits: Decimal, ws_calc_result: Decimal) -> Decimal:
    """
    Calculates capital ratios based on total deposits
    The result is calculated as total deposits multiplied by 0.08
    Args:
        ws_total_deposits: Total deposit amount (must be positive)
        ws_calc_result: Variable to store the result

    Returns:
        Decimal: Calculated capital ratio
    Raises:
        ValueError: If ws_total_deposits is negative
    """
    logger.info("Executing B110-capital_ratios")
    try:
        if ws_total_deposits < 0:
            logger.error("Total deposits cannot be negative.")
            raise ValueError("Total deposits cannot be negative.")

        ws_calc_result = ws_total_deposits * Decimal('0.08')
        return ws_calc_result
    except Exception as e:
        logger.error(f"Error in B110-capital_ratios: {e}")
        raise

def b120_leverage_ratio_C4(ws_total_deposits: Decimal, ws_total_loans: Decimal, ws_calc_result: Decimal) -> Decimal:
    """
    Calculates the leverage ratio
    Calculated as total deposits divided by total loans
    Args:
        ws_total_deposits: Total deposit amount
        ws_total_loans: Total loan amount (must be positive)
        ws_calc_result: Variable to store the result

    Returns:
        Decimal: Calculated leverage ratio
    Raises:
        ValueError: If ws_total_loans is zero or negative
    """
    logger.info("Executing B120-leverage_ratio")
    try:
        if ws_total_loans <= 0:
            logger.error("Total loans must be positive.")
            raise ValueError("Total loans must be positive.")
        
        ws_calc_result = ws_total_deposits / ws_total_loans
        return ws_calc_result

    except Exception as e:
        logger.error(f"Error in B120-leverage_ratio: {e}")
        raise

