    try:
        display_message = f"CRITICAL ERROR: {ws_abort_reason}"
        display_message2 = f"PROCESSING ABORTED AT {get_current_date_C6()}"

        print(display_message)  # Simulates DISPLAY
        logger.error(display_message)
        print(display_message2)  # Simulates DISPLAY
        logger.error(display_message2)

        close_files_C6() # Calls close files
        
        # Simulate STOP RUN WITH STATUS 8
        raise SystemExit(8)  # Using SystemExit to terminate with a status code
        logger.critical("System is exiting with status 8") # Critical instead of error
        
    except Exception as e:
        logger.exception(f"Unexpected error during abort process: {e}") #Exception since exiting
        raise

