# Configure logging
logger = logging.getLogger(__name__)
logging.basicConfig(level=logging.INFO)

def calculate_pmi_C7(ws_ltv_ratio: Decimal, ws_loan_amount: Decimal) -> Decimal:
    """
    Calculate PMI amount based on LTV ratio
    PMI (Private Mortgage Insurance) is calculated based on the Loan-To-Value (LTV) ratio
    The higher the LTV, the higher the risk for the lender and the higher the PMI
    Args:
        ws_ltv_ratio: Loan-to-value ratio (e.g., 95 for 95%) as a Decimal
        ws_loan_amount: The loan amount as a Decimal
    Returns:
        Decimal: The calculated PMI amount, rounded to 2 decimal places
    Raises:
        ValueError: If ws_ltv_ratio or ws_loan_amount are negative
    """
    logger.info(f"Calculating PMI for LTV ratio {ws_ltv_ratio} and loan amount {ws_loan_amount}")
    
    # Input validation
    if ws_ltv_ratio < Decimal('0'):
        logger.error(f"Invalid LTV ratio: {ws_ltv_ratio}")
        raise ValueError(f"LTV ratio cannot be negative: {ws_ltv_ratio}")
    
    if ws_loan_amount < Decimal('0'):
        logger.error(f"Invalid loan amount: {ws_loan_amount}")
        raise ValueError(f"Loan amount cannot be negative: {ws_loan_amount}")
    
    try:
        if ws_ltv_ratio > Decimal('95'):
            ws_pmi_amount = ws_loan_amount * Decimal('0.0125') / Decimal('12')
            logger.debug(f"PMI calculated with 1.25% rate: {ws_pmi_amount}")
        elif ws_ltv_ratio > Decimal('90'):
            ws_pmi_amount = ws_loan_amount * Decimal('0.0100') / Decimal('12')
            logger.debug(f"PMI calculated with 1.00% rate: {ws_pmi_amount}")
        elif ws_ltv_ratio > Decimal('85'):
            ws_pmi_amount = ws_loan_amount * Decimal('0.0075') / Decimal('12')
            logger.debug(f"PMI calculated with 0.75% rate: {ws_pmi_amount}")
        else:
            ws_pmi_amount = ws_loan_amount * Decimal('0.0050') / Decimal('12')
            logger.debug(f"PMI calculated with 0.50% rate: {ws_pmi_amount}")
        
        ws_pmi_amount = ws_pmi_amount.quantize(Decimal('0.01'))
        logger.info(f"Final PMI amount: {ws_pmi_amount}")
        return ws_pmi_amount
        
    except Exception as e:
        logger.error(f"PMI calculation failed: {e}")
        raise

def evaluate_history_C7(
    ws_late_90_days: int,
    ws_late_60_days: int,
    ws_late_30_days: int,
    ws_risk_score: int
) -> tuple[int, str, str, str]:
    """
    Evaluate credit history and adjust risk score
    This function evaluates the number of late payments in different timeframes
    and adjusts the risk score accordingly.  It also sets factors that contribute
    to the risk score
    Args:
        ws_late_90_days: Number of payments late by 90 days or more
        ws_late_60_days: Number of payments late by 60 days
        ws_late_30_days: Number of payments late by 30 days
        ws_risk_score: Current risk score
    Returns:
        tuple[int, str, str, str]: Updated risk score, WS_FACTOR_1, WS_FACTOR_2, WS_FACTOR_3
    Raises:
        ValueError: If any input is negative
    """
    logger.info(f"Evaluating history with late payments: 90={ws_late_90_days}, 60={ws_late_60_days}, 30={ws_late_30_days} and risk score {ws_risk_score}")
    
    # Input validation
    if ws_late_90_days < 0 or ws_late_60_days < 0 or ws_late_30_days < 0 or ws_risk_score < 0:
        logger.error("Negative input(s) detected")
        raise ValueError("Number of late days and risk score cannot be negative.")
    
    ws_factor_1 = ""
    ws_factor_2 = ""
    ws_factor_3 = ""
    
    try:
        if ws_late_90_days > 0:
            ws_risk_score -= 50
            ws_factor_1 = 'SEVERE DELINQUENCY HISTORY'
            logger.debug(f"Risk score reduced by 50 due to 90+ day lates.  New score = {ws_risk_score}")
        
        if ws_late_60_days > 2:
            ws_risk_score -= 30
            ws_factor_2 = '60+ DAY DELINQUENCIES'
            logger.debug(f"Risk score reduced by 30 due to 60+ day lates.  New score = {ws_risk_score}")
        
        if ws_late_30_days > 5:
            ws_risk_score -= 20
            ws_factor_3 = 'MULTIPLE 30-DAY LATES'
            logger.debug(f"Risk score reduced by 20 due to multiple 30 day lates.  New score = {ws_risk_score}")
        
        logger.info(f"Updated risk score: {ws_risk_score}")
        return ws_risk_score, ws_factor_1, ws_factor_2, ws_factor_3
        
    except Exception as e:
        logger.error(f"History evaluation failed: {e}")
        raise

def calculate_final_risk_C7(ws_risk_score: Decimal) -> tuple[Decimal, str]:
    """
    Calculate the final risk score and determine risk category
    This function calculates the final risk score by dividing the initial
    risk score by 4 and then assigns a risk category based on the final score
    Args:
        ws_risk_score: The initial risk score (Decimal)
    Returns:
        tuple[Decimal, str]: The final risk score and risk category
    Raises:
        ValueError: If the input risk score is negative
    """
    logger.info(f"Calculating final risk with initial score: {ws_risk_score}")
    
    # Input validation
    if ws_risk_score < Decimal('0'):
        logger.error(f"Invalid risk score: {ws_risk_score}")
        raise ValueError(f"Risk score cannot be negative: {ws_risk_score}")
    
    try:
        ws_risk_score = ws_risk_score / Decimal('4')
        logger.debug(f"Risk score divided by 4: {ws_risk_score}")
        ws_risk_score = ws_risk_score.quantize(Decimal('0'))
        logger.debug(f"Risk score quantized: {ws_risk_score}")
        
        if ws_risk_score >= Decimal('80'):
            ws_risk_category = 'LOW RISK'
            logger.debug("Risk category assigned: LOW RISK")
        elif ws_risk_score >= Decimal('60'):
            ws_risk_category = 'MODERATE'
            logger.debug("Risk category assigned: MODERATE")
        elif ws_risk_score >= Decimal('40'):
            ws_risk_category = 'ELEVATED'
            logger.debug("Risk category assigned: ELEVATED")
        else:
            ws_risk_category = 'HIGH RISK'
            logger.debug("Risk category assigned: HIGH RISK")
        
        logger.info(f"Final risk score: {ws_risk_score}, category: {ws_risk_category}")
        return ws_risk_score, ws_risk_category
        
    except Exception as e:
        logger.error(f"Final risk calculation failed: {e}")
        raise

def determine_approval_C7(ws_credit_tier: str, ws_risk_category: str, ws_dti_ratio: Decimal) -> tuple[str, str]:
    """
    Determine loan approval status based on credit tier, risk category, and DTI ratio
    This function determines the loan approval status based on the applicant's'
    credit tier, risk category, and debt-to-income (DTI) ratio
    Args:
        ws_credit_tier: Credit tier of the applicant (e.g., 'A', 'B', 'C', 'D', 'F')
        ws_risk_category: Risk category of the applicant (e.g., 'LOW RISK', 'MODERATE', 'ELEVATED', 'HIGH RISK')
        ws_dti_ratio: Debt-to-income ratio as a Decimal
    Returns:
        tuple[str, str]: Approval status ('A' for Approved, 'D' for Declined) and conditions
    Raises:
        ValueError: If any input is invalid
    """
    logger.info(f"Determining approval with credit tier {ws_credit_tier}, risk category {ws_risk_category}, and DTI ratio {ws_dti_ratio}")
    
    # Input validation
    valid_credit_tiers = ['A', 'B', 'C', 'D', 'F']
    valid_risk_categories = ['LOW RISK', 'MODERATE', 'ELEVATED', 'HIGH RISK']
    
    if ws_credit_tier not in valid_credit_tiers:
        logger.error(f"Invalid credit tier: {ws_credit_tier}")
        raise ValueError(f"Invalid credit tier: {ws_credit_tier}. Valid tiers are {valid_credit_tiers}")
    
    if ws_risk_category not in valid_risk_categories:
        logger.error(f"Invalid risk category: {ws_risk_category}")
        raise ValueError(f"Invalid risk category: {ws_risk_category}. Valid categories are {valid_risk_categories}")
    
    if ws_dti_ratio < Decimal('0'):
        logger.error(f"Invalid DTI ratio: {ws_dti_ratio}")
        raise ValueError(f"DTI ratio cannot be negative: {ws_dti_ratio}")
    
    ws_approval_status = ""
    ws_conditions = ""
    
    try:
        if ws_credit_tier == 'F':
            ws_approval_status = 'D'
            ws_conditions = 'CREDIT SCORE TOO LOW'
            logger.debug(f"Application declined due to low credit score.")
            return ws_approval_status, ws_conditions
        
        if ws_risk_category == 'HIGH RISK':
            ws_approval_status = 'D'
            ws_conditions = 'RISK ASSESSMENT FAILED'
            logger.debug(f"Application declined due to risk assessment failure.")
            return ws_approval_status, ws_conditions
        
        if ws_dti_ratio > Decimal('50'):
            ws_approval_status = 'D'
            ws_conditions = 'DTI RATIO TOO HIGH'
            logger.debug(f"Application declined due to high DTI ratio.")
            return ws_approval_status, ws_conditions
        
        ws_approval_status = 'A'
        logger.debug(f"Application pre-approved")
        # PERFORM 10450-calculate_approved_terms (assume function exists)
        ws_approved_amount, ws_approved_rate = calculate_approved_terms_C7(ws_credit_tier, ws_risk_category)
        logger.debug(f"Calculated approved terms, amount {ws_approved_amount}, rate {ws_approved_rate}")
        
        logger.info(f"Final approval status: {ws_approval_status}, conditions: {ws_conditions}")
        return ws_approval_status, ws_conditions
        
    except Exception as e:
        logger.error(f"Approval determination failed: {e}")
        raise

def calculate_approved_terms_C7(ws_credit_tier: str, ws_risk_category: str) -> tuple[Decimal, Decimal]:
    """
    Calculate the approved loan amount and interest rate based on credit tier and risk category
    The function determines the approved loan amount (currently just the initial loan
    amount) and calculates the approved interest rate based on the credit tier and risk
    category
    Args:
        ws_credit_tier: Credit tier of the applicant ('A', 'B', 'C', or 'D')
        ws_risk_category: Risk category of the applicant ('ELEVATED', or other values)
    Returns:
        tuple[Decimal, Decimal]: Approved loan amount and approved interest rate
    Raises:
        ValueError: If the credit tier is invalid
    """
    #Dummy Data for now, to get it working
    ws_loan_amount = Decimal(50000)
    ws_base_rate = Decimal(0.05)

    logger.info(f"Calculating approved terms with credit tier {ws_credit_tier} and risk category {ws_risk_category}")
    
    # Input validation
    valid_credit_tiers = ['A', 'B', 'C', 'D']
    if ws_credit_tier not in valid_credit_tiers:
        logger.error(f"Invalid credit tier: {ws_credit_tier}")
        raise ValueError(f"Invalid credit tier: {ws_credit_tier}. Valid tiers are {valid_credit_tiers}")
    
    try:
        ws_approved_amount = ws_loan_amount
        logger.debug(f"Approved amount set to loan amount: {ws_approved_amount}")
        
        if ws_credit_tier == 'A':
            ws_approved_rate = ws_base_rate + Decimal('0.00')
            logger.debug(f"Rate set to base rate for tier A")
        elif ws_credit_tier == 'B':
            ws_approved_rate = ws_base_rate + Decimal('0.0050')
            logger.debug(f"Rate set to base rate + 0.50 for tier B")
        elif ws_credit_tier == 'C':
            ws_approved_rate = ws_base_rate + Decimal('0.0150')
            logger.debug(f"Rate set to base rate + 1.50 for tier C")
        elif ws_credit_tier == 'D':
            ws_approved_rate = ws_base_rate + Decimal('0.0300')
            logger.debug(f"Rate set to base rate + 3.00 for tier D")
        else:
             #This point will not be reached given validation above
             ws_approved_rate = ws_base_rate + Decimal('0.00')
        
        if ws_risk_category == 'ELEVATED':
            ws_approved_rate += Decimal('0.0050')
            logger.debug(f"Rate increased by 0.50 due to elevated risk")
        
        logger.info(f"Final approved amount: {ws_approved_amount}, rate: {ws_approved_rate}")
        return ws_approved_amount, ws_approved_rate
        
    except Exception as e:
        logger.error(f"Approved terms calculation failed: {e}")
        raise

def generate_loan_terms_C7(
    ws_approved_rate: Decimal,
    ws_loan_term_months: int,
    ws_loan_amount: Decimal
) -> tuple[Decimal, Decimal, Decimal]:
    """
    Generate loan terms including monthly rate, compound factor, and monthly payment
    This function calculates the loan terms based on the approved interest rate,
    loan term in months, and loan amount
    Args:
        ws_approved_rate: Approved annual interest rate as a Decimal (e.g., 0.05 for 5%)
        ws_loan_term_months: Loan term in months (integer)
        ws_loan_amount: Loan amount as a Decimal
    Returns:
        tuple[Decimal, Decimal, Decimal]: Monthly interest rate, compound factor, and loan monthly payment
    Raises:
        ValueError: If any input is invalid
    """
    logger.info(f"Generating loan terms with rate {ws_approved_rate}, term {ws_loan_term_months}, and amount {ws_loan_amount}")
    
    # Input validation
    if ws_approved_rate < Decimal('0'):
        logger.error(f"Invalid approved rate: {ws_approved_rate}")
        raise ValueError(f"Approved rate cannot be negative: {ws_approved_rate}")
    
    if ws_loan_term_months <= 0:
        logger.error(f"Invalid loan term: {ws_loan_term_months}")
        raise ValueError(f"Loan term must be a positive integer: {ws_loan_term_months}")
    
    if ws_loan_amount < Decimal('0'):
        logger.error(f"Invalid loan amount: {ws_loan_amount}")
        raise ValueError(f"Loan amount cannot be negative: {ws_loan_amount}")
    
    try:
        ws_loan_interest_rate = ws_approved_rate
        logger.debug(f"Loan interest rate set: {ws_loan_interest_rate}")
        
        ws_monthly_rate = ws_loan_interest_rate / Decimal('1200')
        logger.debug(f"Monthly rate calculated: {ws_monthly_rate}")
        
        ws_compound_factor = (Decimal('1') + ws_monthly_rate) ** ws_loan_term_months
        logger.debug(f"Compound factor calculated: {ws_compound_factor}")
        
        ws_loan_monthly_pmt = (ws_loan_amount * ws_monthly_rate * ws_compound_factor) / (ws_compound_factor - Decimal('1'))
        logger.debug(f"Monthly payment calculated: {ws_loan_monthly_pmt}")
        ws_loan_monthly_pmt = ws_loan_monthly_pmt.quantize(Decimal('0.01'))
        logger.debug(f"Monthly Payment Quantized: {ws_loan_monthly_pmt}")
        
        logger.info(f"Loan terms generated: monthly rate {ws_monthly_rate}, compound factor {ws_compound_factor}, monthly payment {ws_loan_monthly_pmt}")
        return ws_monthly_rate, ws_compound_factor, ws_loan_monthly_pmt
        
    except Exception as e:
        logger.error(f"Loan terms generation failed: {e}")
        raise

def create_amortization_C7(
    ws_loan_amount: Decimal,
    ws_loan_term_months: int,
    ws_monthly_rate: Decimal,
    ws_loan_monthly_pmt: Decimal,
    loan_mortgage: bool,
    ws_property_tax: Decimal,
    ws_insurance_premium: Decimal,
    ws_pmi_amount: Decimal
) -> list[dict]:
    """
    Create an amortization schedule for the loan
    This function generates an amortization schedule with payment splits for interest,
    principal, and escrow (if applicable)
    Args:
        ws_loan_amount: The original loan amount
        ws_loan_term_months: The loan term in months
        ws_monthly_rate: The monthly interest rate
        ws_loan_monthly_pmt: The fixed monthly loan payment
        loan_mortgage: A boolean indicating if it is a mortgage loan, impacting escrow calculations
        ws_property_tax: Annual property tax amount
        ws_insurance_premium: Annual insurance premium amount
        ws_pmi_amount: PMI amount
    Returns:
        list[dict]: A list of dictionaries, each representing a payment in the amortization schedule
    Raises:
        ValueError: If any input is invalid
    """
    logger.info(f"Creating amortization schedule for loan amount {ws_loan_amount} with term {ws_loan_term_months}")
    
    # Input validation
    if ws_loan_amount < Decimal('0'):
        logger.error(f"Invalid loan amount: {ws_loan_amount}")
        raise ValueError(f"Loan amount cannot be negative: {ws_loan_amount}")
    
    if ws_loan_term_months <= 0:
        logger.error(f"Invalid loan term: {ws_loan_term_months}")
        raise ValueError(f"Loan term must be a positive integer: {ws_loan_term_months}")
    
    if ws_monthly_rate < Decimal('0'):
        logger.error(f"Invalid monthly rate: {ws_monthly_rate}")
        raise ValueError(f"Monthly rate cannot be negative: {ws_monthly_rate}")
    
    if ws_loan_monthly_pmt < Decimal('0'):
        logger.error(f"Invalid loan monthly payment: {ws_loan_monthly_pmt}")
        raise ValueError(f"Loan monthly payment cannot be negative: {ws_loan_monthly_pmt}")
    
    try:
        ws_running_balance = ws_loan_amount
        logger.debug(f"Initial running balance set to loan amount: {ws_running_balance}")
        
        ws_payment_date = date.today()
        logger.debug(f"Initial payment date set to today: {ws_payment_date}")
        
        ws_payment_month = ws_payment_date.month
        ws_payment_year = ws_payment_date.year
        
        amortization_schedule = []
        
        for ws_amort_idx in range(1, ws_loan_term_months + 1):
            amort_payment = calculate_payment_split_C7(
                ws_running_balance,
                ws_monthly_rate,
                ws_loan_monthly_pmt,
                loan_mortgage,
                ws_property_tax,
                ws_insurance_premium,
                ws_pmi_amount,
                ws_amort_idx,
                ws_payment_month,
                ws_payment_year
            )
            
            amort_payment_date = advance_payment_date_C7(amort_payment['WS_PAYMENT_MONTH'], amort_payment['WS_PAYMENT_YEAR'])
            ws_payment_month = amort_payment_date[0]
            ws_payment_year = amort_payment_date[1]
                
            ws_running_balance = amort_payment['AMORT_BALANCE']
            amortization_schedule.append(amort_payment)
        
        logger.info(f"Amortization schedule created successfully")
        return amortization_schedule
        
    except Exception as e:
        logger.error(f"Amortization schedule creation failed: {e}")
        raise

def calculate_payment_split_C7(
    ws_running_balance: Decimal,
    ws_monthly_rate: Decimal,
    ws_loan_monthly_pmt: Decimal,
    loan_mortgage: bool,
    ws_property_tax: Decimal,
    ws_insurance_premium: Decimal,
    ws_pmi_amount: Decimal,
    ws_amort_idx: int,
    ws_payment_month: int,
    ws_payment_year: int
) -> dict:
    """
    Calculate the payment split for a given payment period
    This function calculates the interest and principal portions of the payment, updates
    the running balance, and includes escrow calculations if the loan is a mortgage
    Args:
        ws_running_balance: The remaining balance on the loan
        ws_monthly_rate: The monthly interest rate
        ws_loan_monthly_pmt: The fixed monthly loan payment
        loan_mortgage: A boolean indicating if it is a mortgage loan
        ws_property_tax: Annual property tax amount
        ws_insurance_premium: Annual insurance premium amount
        ws_pmi_amount: PMI amount
        ws_amort_idx: Index of the amortization payment
        ws_payment_month: Current month of the payment schedule
        ws_payment_year: Current year of the payment schedule
    Returns:
        dict: A dictionary containing the payment split details
    Raises:
        ValueError: If any input is invalid
    """
    logger.debug(f"Calculating payment split for period {ws_amort_idx}")
    
    # Input validation
    if ws_running_balance < Decimal('0'):
        logger.error(f"Invalid running balance: {ws_running_balance}")
        raise ValueError(f"Running balance cannot be negative: {ws_running_balance}")
    
    if ws_monthly_rate < Decimal('0'):
        logger.error(f"Invalid monthly rate: {ws_monthly_rate}")
        raise ValueError(f"Monthly rate cannot be negative: {ws_monthly_rate}")
    
    if ws_loan_monthly_pmt < Decimal('0'):
        logger.error(f"Invalid loan monthly payment: {ws_loan_monthly_pmt}")
        raise ValueError(f"Loan monthly payment cannot be negative: {ws_loan_monthly_pmt}")
    
    try:
        amort_interest = ws_running_balance * ws_monthly_rate
        amort_interest = amort_interest.quantize(Decimal('0.01'))
        logger.debug(f"Interest portion: {amort_interest}")
        
        amort_principal = ws_loan_monthly_pmt - amort_interest
        amort_principal = amort_principal.quantize(Decimal('0.01'))
        logger.debug(f"Principal portion: {amort_principal}")
        
        ws_running_balance -= amort_principal
        ws_running_balance = ws_running_balance.quantize(Decimal('0.01'))
        logger.debug(f"Updated running balance: {ws_running_balance}")
        
        amort_balance = ws_running_balance
        amort_payment_num = ws_amort_idx
        amort_payment_amt = ws_loan_monthly_pmt
        
        if loan_mortgage:
            amort_escrow = (ws_property_tax + ws_insurance_premium) / Decimal('12')
            amort_escrow = amort_escrow.quantize(Decimal('0.01'))
            amort_total_pmt = ws_loan_monthly_pmt + amort_escrow + ws_pmi_amount
            amort_total_pmt = amort_total_pmt.quantize(Decimal('0.01'))
            logger.debug(f"Total payment with escrow: {amort_total_pmt}")
        else:
            amort_escrow = Decimal("0") #Ensure variable initialization
            amort_total_pmt = ws_loan_monthly_pmt
            logger.debug(f"Total payment: {amort_total_pmt}")
        
        payment_details = {
            'AMORT_INTEREST': amort_interest,
            'AMORT_PRINCIPAL': amort_principal,
            'AMORT_BALANCE': amort_balance,
            'AMORT_PAYMENT_NUM': amort_payment_num,
            'AMORT_PAYMENT_AMT': amort_payment_amt,
            'AMORT_ESCROW': amort_escrow,
            'AMORT_TOTAL_PMT': amort_total_pmt,
            'WS_PAYMENT_MONTH': ws_payment_month,
            'WS_PAYMENT_YEAR': ws_payment_year
        }
        
        logger.info(f"Payment split calculated successfully")
        return payment_details
        
    except Exception as e:
        logger.error(f"Payment split calculation failed: {e}")
        raise

def advance_payment_date_C7(ws_payment_month: int, ws_payment_year: int) -> tuple[int, int]:
    """
    Advance the payment date by one month
    This function increments the month and year for the next payment date
    Args:
        ws_payment_month: Current month of the payment schedule
        ws_payment_year: Current year of the payment schedule
    Returns:
        tuple[int, int]: Updated month and year for the next payment
    Raises:
        ValueError: If the initial month or year is invalid
    """
    logger.debug(f"Advancing payment date from month {ws_payment_month} and year {ws_payment_year}")
    
    # Input validation
    if ws_payment_month < 1 or ws_payment_month > 12:
        logger.error(f"Invalid payment month: {ws_payment_month}")
        raise ValueError(f"Payment month must be between 1 and 12: {ws_payment_month}")
    
    if ws_payment_year < 1900:
        logger.error(f"Invalid payment year: {ws_payment_year}")
        raise ValueError(f"Payment year must be greater than 1900: {ws_payment_year}")
    
    try:
        ws_payment_month += 1
        if ws_payment_month > 12:
            ws_payment_month = 1
            ws_payment_year += 1
        
        logger.debug(f"Next payment date: month {ws_payment_month}, year {ws_payment_year}")
        return ws_payment_month, ws_payment_year
        
    except Exception as e:
        logger.error(f"Payment date advancement failed: {e}")
        raise

