logger = logging.getLogger(__name__)

def calc_auto_premium_C8(
    ws_driver_age: int,
    ws_accidents_3yr: int,
    ws_violations_3yr: int,
    ws_base_premium: Decimal
) -> Decimal:
    """
    Calculates the auto insurance premium based on driver age,
    accidents, violations and base premium
    The calculation is based on the following rules:
    - If driver age is between 6 and 10, add 100 to base premium
    - If driver age is other than above, add 50 to base premium
    - If driver age is less than 25, multiply base premium by 1.5
    - If accidents in last 3 years are greater than 0, add surcharge to base premium
    - If violations in last 3 years are greater than 0, add violation surcharge to base premium
    Finally ws_base_premium will be moved to ws_annual_premium and ws_monthly_premium calculated
    Args:
        ws_driver_age: Driver age
        ws_accidents_3yr: Number of accidents in the last 3 years
        ws_violations_3yr: Number of violations in the last 3 years
        ws_base_premium: Base premium amount

    Returns:
        Decimal: Monthly premium calculated

    Raises:
        ValueError: If inputs are invalid
    """
    logger.info("Starting auto premium calculation")

    # Input validation
    if not isinstance(ws_driver_age, int):
        logger.error("Invalid driver age")
        raise ValueError("Driver age must be an integer")
    if not isinstance(ws_accidents_3yr, int):
        logger.error("Invalid accidents count")
        raise ValueError("Accidents count must be an integer")
    if not isinstance(ws_violations_3yr, int):
        logger.error("Invalid violations count")
        raise ValueError("Violations count must be an integer")
    if not isinstance(ws_base_premium, Decimal):
        logger.error("Invalid base premium")
        raise ValueError("Base premium must be a Decimal")
    
    try:
        # Evaluate driver age
        if 6 <= ws_driver_age <= 10:
            ws_base_premium += Decimal('100')
            logger.debug("Added 100 to base premium due to driver age.")
        else:
            ws_base_premium += Decimal('50')
            logger.debug("Added 50 to base premium due to driver age.")

        # Adjust premium based on driver age
        if ws_driver_age < 25:
            ws_base_premium *= Decimal('1.5')
            logger.debug("Multiplied base premium by 1.5 due to driver age < 25.")

        # Add accident surcharge
        if ws_accidents_3yr > 0:
            ws_accident_surcharge = Decimal(ws_accidents_3yr * 200)
            ws_base_premium += ws_accident_surcharge
            logger.debug("Added accident surcharge to base premium.")

        # Add violation surcharge
        if ws_violations_3yr > 0:
            ws_violation_surcharge = Decimal(ws_violations_3yr * 100)
            ws_base_premium += ws_violation_surcharge
            logger.debug("Added violation surcharge to base premium.")

        ws_annual_premium = ws_base_premium
        ws_monthly_premium = ws_annual_premium / Decimal('12')
        logger.info(f"Calculated monthly premium {ws_monthly_premium}")

        return ws_monthly_premium
    except Exception as e:
        logger.error(f"Error during premium calculation: {e}")
        raise

def calc_home_premium_C8(
    ws_coverage_amount: Decimal,
    ws_home_age: int,
    ws_flood_zone: str,
    ws_security_system: str,
    ws_deductible: int
) -> Decimal:
    """
    Calculates the home insurance premium based on coverage amount,
    home age, flood zone, security system and deductible
    The calculation is based on the following rules:
    - Base premium = coverage amount * 0.003
    - Adjust base premium based on home age:
      - 0-10 years: multiply by 0.9
      - 11-25 years: multiply by 1.0
      - 26-50 years: multiply by 1.2
      - Other: multiply by 1.5
    - If flood zone is 'Y', multiply base premium by 1.5
    - If security system is 'Y', multiply base premium by 0.9
    - Deductible credit = deductible / 1000 * 50
    - Subtract deductible credit from base premium
    - If base premium is less than 200, set it to 200

    Args:
        ws_coverage_amount: Coverage amount
        ws_home_age: Home age
        ws_flood_zone: Flood zone indicator ('Y' or other)
        ws_security_system: Security system indicator ('Y' or other)
        ws_deductible: Deductible amount

    Returns:
        Decimal: Monthly premium calculated

    Raises:
        ValueError: If inputs are invalid
    """
    logger.info("Starting home premium calculation")

    # Input validation
    if not isinstance(ws_coverage_amount, Decimal):
        logger.error("Invalid coverage amount")
        raise ValueError("Coverage amount must be a Decimal")
    if not isinstance(ws_home_age, int):
        logger.error("Invalid home age")
        raise ValueError("Home age must be an integer")
    if not isinstance(ws_flood_zone, str):
        logger.error("Invalid flood zone")
        raise ValueError("Flood zone must be a string")
    if not isinstance(ws_security_system, str):
        logger.error("Invalid security system")
        raise ValueError("Security system must be a string")
    if not isinstance(ws_deductible, int):
        logger.error("Invalid deductible")
        raise ValueError("Deductible must be an integer")

    try:
        # Calculate base premium
        ws_base_premium = ws_coverage_amount * Decimal('0.003')
        logger.debug(f"Initial base premium: {ws_base_premium}")

        # Adjust premium based on home age
        if 0 <= ws_home_age <= 10:
            ws_base_premium *= Decimal('0.9')
            logger.debug("Multiplied base premium by 0.9 due to home age.")
        elif 11 <= ws_home_age <= 25:
            ws_base_premium *= Decimal('1.0')
            logger.debug("Multiplied base premium by 1.0 due to home age.")
        elif 26 <= ws_home_age <= 50:
            ws_base_premium *= Decimal('1.2')
            logger.debug("Multiplied base premium by 1.2 due to home age.")
        else:
            ws_base_premium *= Decimal('1.5')
            logger.debug("Multiplied base premium by 1.5 due to home age.")

        # Adjust premium based on flood zone
        if ws_flood_zone == 'Y':
            ws_base_premium *= Decimal('1.5')
            logger.debug("Multiplied base premium by 1.5 due to flood zone.")

        # Adjust premium based on security system
        if ws_security_system == 'Y':
            ws_base_premium *= Decimal('0.9')
            logger.debug("Multiplied base premium by 0.9 due to security system.")

        # Calculate deductible credit
        ws_deductible_credit = Decimal(ws_deductible / 1000 * 50)
        ws_base_premium -= ws_deductible_credit
        logger.debug(f"Deductible credit: {ws_deductible_credit}")

        # Ensure minimum base premium
        if ws_base_premium < Decimal('200'):
            ws_base_premium = Decimal('200')
            logger.debug("Base premium set to minimum of 200.")

        ws_annual_premium = ws_base_premium
        ws_monthly_premium = ws_annual_premium / Decimal('12')
        logger.info(f"Calculated monthly premium {ws_monthly_premium}")

        return ws_monthly_premium
    except Exception as e:
        logger.error(f"Error during premium calculation: {e}")
        raise

def calc_health_premium_C8(
    ws_insured_age: int,
    ws_plan_type: str,
    ws_family_plan: str
) -> Decimal:
    """
    Calculates the health insurance premium based on insured age,
    plan type and family plan
    The calculation is based on the following rules:
    - Initial base premium is 300
    - Adjust base premium based on insured age:
      - 0-18 years: multiply by 0.5
      - 19-30 years: multiply by 1.0
      - 31-40 years: multiply by 1.3
      - 41-50 years: multiply by 1.6
      - 51-60 years: multiply by 2.0
      - Other: multiply by 2.8
    - Adjust base premium based on plan type:
      - 'BRONZE': multiply by 0.8
      - 'SILVER': multiply by 1.0
      - 'GOLD': multiply by 1.3
      - 'PLATINUM': multiply by 1.6
    - If family plan is 'Y', multiply base premium by 2.5

    Args:
        ws_insured_age: Insured age
        ws_plan_type: Plan type ('BRONZE', 'SILVER', 'GOLD', 'PLATINUM')
        ws_family_plan: Family plan indicator ('Y' or other)

    Returns:
        Decimal: Annual premium calculated

    Raises:
        ValueError: If inputs are invalid
    """
    logger.info("Starting health premium calculation")

    # Input validation
    if not isinstance(ws_insured_age, int):
        logger.error("Invalid insured age")
        raise ValueError("Insured age must be an integer")
    if not isinstance(ws_plan_type, str):
        logger.error("Invalid plan type")
        raise ValueError("Plan type must be a string")
    if not isinstance(ws_family_plan, str):
        logger.error("Invalid family plan")
        raise ValueError("Family plan must be a string")

    try:
        # Set initial base premium
        ws_base_premium = Decimal('300')
        logger.debug(f"Initial base premium: {ws_base_premium}")

        # Adjust premium based on insured age
        if 0 <= ws_insured_age <= 18:
            ws_base_premium *= Decimal('0.5')
            logger.debug("Multiplied base premium by 0.5 due to insured age.")
        elif 19 <= ws_insured_age <= 30:
            ws_base_premium *= Decimal('1.0')
            logger.debug("Multiplied base premium by 1.0 due to insured age.")
        elif 31 <= ws_insured_age <= 40:
            ws_base_premium *= Decimal('1.3')
            logger.debug("Multiplied base premium by 1.3 due to insured age.")
        elif 41 <= ws_insured_age <= 50:
            ws_base_premium *= Decimal('1.6')
            logger.debug("Multiplied base premium by 1.6 due to insured age.")
        elif 51 <= ws_insured_age <= 60:
            ws_base_premium *= Decimal('2.0')
            logger.debug("Multiplied base premium by 2.0 due to insured age.")
        else:
            ws_base_premium *= Decimal('2.8')
            logger.debug("Multiplied base premium by 2.8 due to insured age.")

        # Adjust premium based on plan type
        if ws_plan_type == 'BRONZE':
            ws_base_premium *= Decimal('0.8')
            logger.debug("Multiplied base premium by 0.8 due to Bronze plan.")
        elif ws_plan_type == 'SILVER':
            ws_base_premium *= Decimal('1.0')
            logger.debug("Multiplied base premium by 1.0 due to Silver plan.")
        elif ws_plan_type == 'GOLD':
            ws_base_premium *= Decimal('1.3')
            logger.debug("Multiplied base premium by 1.3 due to Gold plan.")
        elif ws_plan_type == 'PLATINUM':
            ws_base_premium *= Decimal('1.6')
            logger.debug("Multiplied base premium by 1.6 due to Platinum plan.")

        # Adjust premium based on family plan
        if ws_family_plan == 'Y':
            ws_base_premium *= Decimal('2.5')
            logger.debug("Multiplied base premium by 2.5 due to family plan.")

        ws_monthly_premium = ws_base_premium
        ws_annual_premium = ws_monthly_premium * Decimal('12')
        logger.info(f"Calculated annual premium {ws_annual_premium}")

        return ws_annual_premium
    except Exception as e:
        logger.error(f"Error during premium calculation: {e}")
        raise

