def determine_decision_C8():
    """
    Determines underwriting decision based on risk points
    This includes setting underwriting decision and adjusting annual
    premium based on risk points
    """
    logger.info("Determining underwriting decision")
    try:
        ws_risk_points = globals().get('WS_RISK_POINTS', 0) #Default value in case evaluate risk factors is skipped
        ws_annual_premium = globals().get('WS_ANNUAL_PREMIUM', Decimal('1000')) #Default value in case premium calculation is skipped
        if ws_risk_points > 50:
            globals()['WS_UW_DECISION'] = 'DECLINE'
            logger.debug("Underwriting decision: DECLINE")
        elif ws_risk_points > 30:
            globals()['WS_UW_DECISION'] = 'SUBSTANDARD'
            ws_annual_premium *= Decimal('1.5')
            globals()['WS_ANNUAL_PREMIUM'] = ws_annual_premium #Update global value
            logger.debug(f"Underwriting decision: SUBSTANDARD, annual premium adjusted to {ws_annual_premium}")
        elif ws_risk_points > 15:
            globals()['WS_UW_DECISION'] = 'STANDARD'
            logger.debug("Underwriting decision: STANDARD")
        else:
            globals()['WS_UW_DECISION'] = 'PREFERRED'
            ws_annual_premium *= Decimal('0.9')
            globals()['WS_ANNUAL_PREMIUM'] = ws_annual_premium #Update global value
            logger.debug(f"Underwriting decision: PREFERRED, annual premium adjusted to {ws_annual_premium}")

    except Exception as e:
        logger.error(f"Error during decision determination: {e}")
        raise

