        claim_amount = globals().get('WS_CLAIM_AMOUNT', Decimal('0'))
        recent_claims = globals().get('WS_RECENT_CLAIMS', 0)

        if recent_claims > 2:
            globals()['WS_FRAUD_REVIEW'] = 'Y'
