logger = logging.getLogger(__name__)

def update_pep_status_C9(ws_pep_status: str, pep_match_score: Decimal) -> None:
    """
    Updates the PEP status based on the PEP match score
    If pep_match_score is greater than 0, updates ws_pep_status to 'Y'
    and moves pep_match_score to ws_pep_score
    Args:
        ws_pep_status: The current PEP status (PIC X(1))
        pep_match_score: The PEP match score (PIC 9(5))
    Returns:
        None: The function modifies the input ws_pep_status
    Raises:
        ValueError: If ws_pep_status is not a string of length 1
        ValueError: If pep_match_score is negative
    """
    logger.info("Entering update_pep_status_C9")

    # Validate inputs
    if not isinstance(ws_pep_status, str) or len(ws_pep_status) != 1:
        logger.error(f"Invalid ws_pep_status: {ws_pep_status}")
        raise ValueError("ws_pep_status must be a string of length 1")

    if not isinstance(pep_match_score, Decimal) or pep_match_score < Decimal('0'):
        logger.error(f"Invalid pep_match_score: {pep_match_score}")
        raise ValueError("pep_match_score must be a non-negative Decimal")

    try:
        # Check if pep_match_score is greater than 0
        if pep_match_score > Decimal('0'):
            logger.debug("pep_match_score is greater than 0")
            # Move 'Y' to ws_pep_status
            ws_pep_status = 'Y'
            # Move pep_match_score to ws_pep_score
            ws_pep_score = pep_match_score #Assuming ws_pep_score is defined in global scope

            logger.debug(f"ws_pep_status updated to: {ws_pep_status}")
            logger.debug(f"ws_pep_score updated to: {ws_pep_score}")
    except Exception as e:
        logger.error(f"Error updating PEP status: {e}")
        raise
    logger.info("Exiting update_pep_status_C9")


def check_adverse_media_C9(
    ws_customer_name: str,
    media_request: Dict[str, Any],
    media_response: Dict[str, Any]
) -> int:
    """
    Checks for adverse media hits using MEDIASRCH
    Moves ws_customer_name to media_search_name, calls MEDIASRCH, and adds media_hits_found
    to ws_watchlist_hits if media_hits_found is greater than 0
    Args:
        ws_customer_name: The customer's name (PIC X(50)).'
        media_request: The request data for MEDIASRCH
        media_response: The response data from MEDIASRCH
    Returns:
        int: The updated value of ws_watchlist_hits

    Raises:
        ValueError: If ws_customer_name is not a string or is empty
    """
    logger.info("Entering check_adverse_media_C9")

    # Validate inputs
    if not isinstance(ws_customer_name, str) or not ws_customer_name:
        logger.error(f"Invalid ws_customer_name: {ws_customer_name}")
        raise ValueError("ws_customer_name must be a non-empty string")

    try:
        # Move ws_customer_name to media_search_name
        media_search_name = ws_customer_name #Assuming media_search_name is defined in global scope
        logger.debug(f"media_search_name updated to: {media_search_name}")

        # Call 'MEDIASRCH'
        mediasrch(media_request, media_response)

        # Check if media_hits_found is greater than 0
        media_hits_found = media_response.get("media_hits_found", 0)
        if media_hits_found > 0:
            logger.debug("media_hits_found is greater than 0")
            # Add media_hits_found to ws_watchlist_hits
            ws_watchlist_hits += media_hits_found #Assuming ws_watchlist_hits is defined in global scope
            logger.debug(f"ws_watchlist_hits updated to: {ws_watchlist_hits}")

        return ws_watchlist_hits
    except Exception as e:
        logger.error(f"Error checking adverse media: {e}")
        raise
    logger.info("Exiting check_adverse_media_C9")


def calculate_match_score_C9(
    ws_ofac_score: Decimal,
    ws_pep_score: Decimal,
    ws_watchlist_hits: int
) -> Decimal:
    """
    Calculates the match score based on OFAC and PEP scores
    Adds ws_ofac_score and ws_pep_score to ws_match_score, then divides ws_match_score
    by ws_watchlist_hits
    Args:
        ws_ofac_score: The OFAC score (PIC 9(3))
        ws_pep_score: The PEP score (PIC 9(3))
        ws_watchlist_hits: The number of watchlist hits (PIC 9(2))
    Returns:
        Decimal: The calculated match score
    Raises:
        ValueError: If ws_ofac_score or ws_pep_score is negative
        ValueError: If ws_watchlist_hits is zero
    """
    logger.info("Entering calculate_match_score_C9")

    # Validate inputs
    if not isinstance(ws_ofac_score, Decimal) or ws_ofac_score < Decimal('0'):
        logger.error(f"Invalid ws_ofac_score: {ws_ofac_score}")
        raise ValueError("ws_ofac_score must be a non-negative Decimal")

    if not isinstance(ws_pep_score, Decimal) or ws_pep_score < Decimal('0'):
        logger.error(f"Invalid ws_pep_score: {ws_pep_score}")
        raise ValueError("ws_pep_score must be a non-negative Decimal")

    if not isinstance(ws_watchlist_hits, int) or ws_watchlist_hits == 0:
        logger.error(f"Invalid ws_watchlist_hits: {ws_watchlist_hits}")
        raise ValueError("ws_watchlist_hits must be a non-zero integer")

    try:
        # Add ws_ofac_score to ws_match_score
        ws_match_score = Decimal('0')  # Assuming ws_match_score is defined in global scope, initialize to 0
        if ws_ofac_score > Decimal('0'):
            ws_match_score += ws_ofac_score
            logger.debug(f"ws_match_score updated with ws_ofac_score: {ws_match_score}")

        # Add ws_pep_score to ws_match_score
        if ws_pep_score > Decimal('0'):
            ws_match_score += ws_pep_score
            logger.debug(f"ws_match_score updated with ws_pep_score: {ws_match_score}")

        # Compute ws_match_score = ws_match_score / ws_watchlist_hits
        ws_match_score = ws_match_score / Decimal(str(ws_watchlist_hits))
        logger.debug(f"ws_match_score updated to: {ws_match_score}")

        return ws_match_score
    except Exception as e:
        logger.error(f"Error calculating match score: {e}")
        raise
    logger.info("Exiting calculate_match_score_C9")


def determine_disposition_C9(ws_match_score: Decimal) -> Dict[str, str]:
    """
    Determines the disposition based on the match score
    Evaluates ws_match_score and sets ws_match_type and ws_sar_required/ws_case_status accordingly
    Args:
        ws_match_score: The match score (PIC 9(3)V99)
    Returns:
        Dict[str, str]: A dictionary containing the updated ws_match_type, ws_sar_required,
                         and ws_case_status
    Raises:
        ValueError: If ws_match_score is negative
    """
    logger.info("Entering determine_disposition_C9")

    # Validate inputs
    if not isinstance(ws_match_score, Decimal) or ws_match_score < Decimal('0'):
        logger.error(f"Invalid ws_match_score: {ws_match_score}")
        raise ValueError("ws_match_score must be a non-negative Decimal")

    try:
        # Initialize variables (assuming they are global scope or part of some larger struct)
        ws_match_type = ""
        ws_sar_required = ""
        ws_case_status = ""

        # Evaluate ws_match_score
        if ws_match_score >= Decimal('90'):
            logger.debug("ws_match_score >= 90")
            ws_match_type = 'CONFIRMED'
            ws_sar_required = 'Y'
        elif ws_match_score >= Decimal('75'):
            logger.debug("ws_match_score >= 75")
            ws_match_type = 'POTENTIAL'
            ws_case_status = 'REVIEW'
        elif ws_match_score >= Decimal('50'):
            logger.debug("ws_match_score >= 50")
            ws_match_type = 'WEAK'
            ws_case_status = 'CLEARED'
        else:
            logger.debug("ws_match_score < 50")
            ws_match_type = 'FALSE POSITIVE'
            ws_case_status = 'CLEARED'

        logger.debug(f"ws_match_type updated to: {ws_match_type}")
        logger.debug(f"ws_sar_required updated to: {ws_sar_required}")
        logger.debug(f"ws_case_status updated to: {ws_case_status}")

        return {
            "ws_match_type": ws_match_type,
            "ws_sar_required": ws_sar_required,
            "ws_case_status": ws_case_status
        }
    except Exception as e:
        logger.error(f"Error determining disposition: {e}")
        raise
    logger.info("Exiting determine_disposition_C9")


