def verify_passport_C9() -> None:
    """
    Verifies the customer's passport using PASSVERIFY.'

    Moves passport information to the PASSPORT request, calls PASSVERIFY, and updates ws_doc_status
    based on the passport verification result
    Args:
       None

    Returns:
        None: Updates global ws_doc_status

    Raises:
        ValueError: If PASSPORT_VALID is not 'Y' or 'N'
    """
    logger.info("Entering verify_passport_C9")

    try:
        # Move passport information to PASSPORT request
        passport_verify_num = ws_passport_number
        passport_verify_country = ws_passport_country

        # Call 'PASSVERIFY'
        passport_req = {'passport_verify_num': passport_verify_num, 'passport_verify_country': passport_verify_country}
        passport_resp = passverify(passport_req)

        passport_valid = passport_resp.get('PASSPORT_VALID')

        # Check if passport_valid = 'Y'
        if passport_valid == 'Y':
            ws_doc_status = 'VERIFIED'
        elif passport_valid == 'N':
            ws_doc_status = 'INVALID'
        else:
            logger.error(f"Invalid passport_valid value: {passport_valid}")
            raise ValueError(f"passport_valid must be 'Y' or 'N', but got {passport_valid}")

        logger.debug(f"ws_doc_status updated to: {ws_doc_status}")
    except Exception as e:
        logger.error(f"Passport verification failed: {e}")
        raise
    logger.info("Exiting verify_passport_C9")


def verify_license_C9() -> None:
    """
    Verifies the customer's license using LICVERIFY.'

    Moves license information to the LICENSE request, calls LICVERIFY, and updates ws_doc_status
    based on the license verification result
    Args:
        None

    Returns:
        None: Updates the global ws_doc_status

    Raises:
        ValueError: If license_valid is not 'Y' or 'N'
    """
    logger.info("Entering verify_license_C9")

    try:
        # Move license information to LICENSE request
        license_verify_num = ws_license_number
        license_verify_state = ws_license_state

        # Call 'LICVERIFY'
        license_req = {'license_verify_num': license_verify_num, 'license_verify_state': license_verify_state}
        license_resp = licverify(license_req)

        license_valid = license_resp.get('LICENSE_VALID')

        # Check if license_valid = 'Y'
        if license_valid == 'Y':
            ws_doc_status = 'VERIFIED'
        elif license_valid == 'N':
            ws_doc_status = 'INVALID'
        else:
            logger.error(f"Invalid license_valid value: {license_valid}")
            raise ValueError(f"license_valid must be 'Y' or 'N', but got {license_valid}")

        logger.debug(f"ws_doc_status updated to: {ws_doc_status}")
    except Exception as e:
        logger.error(f"License verification failed: {e}")
        raise
    logger.info("Exiting verify_license_C9")


