def sum_week_data_C10(ws_weekly_summary: WsWeeklySummaryC10):
    """
    Sums the daily transaction data for the week
    Reads the DAILY_SUMMARY_FILE for the last 7 days and sums the
    transaction counts and amounts into the provided weekly summary object
    """
    logger.info("Starting sum week data")

    global DAILY_SUMMARY_FILE

    ws_weekly_summary.weekly_trans_count = 0
    ws_weekly_summary.weekly_trans_amount = Decimal("0")

    try:
        # Implement reading DAILY_SUMMARY_FILE for the last 7 days
        # This is a simplified approach assuming the file contains data for all days
        daily_data: List[WsDailySummaryC10] = []
        with open(DAILY_SUMMARY_FILE, "r") as f:
            lines = f.readlines()
            # Process only the last 7 lines
            for line in lines[-7:]:
                try:
                    daily_date, daily_trans_count, daily_trans_amount, daily_deposits, daily_withdrawals = line.strip().split(",")
                    daily_data.append(WsDailySummaryC10(
                        daily_date=daily_date,
                        daily_trans_count=int(daily_trans_count),
                        daily_trans_amount=Decimal(daily_trans_amount),
                        daily_deposits=Decimal(daily_deposits),
                        daily_withdrawals=Decimal(daily_withdrawals)
                    ))
                except ValueError as e:
                    logger.warning(f"Skipping invalid line in DAILY_SUMMARY_FILE: {line} - {e}")
                    continue

        for daily_summary in daily_data:
            ws_weekly_summary.weekly_trans_count += daily_summary.daily_trans_count
            ws_weekly_summary.weekly_trans_amount += daily_summary.daily_trans_amount

        logger.debug(f"Summed weekly data: Count={ws_weekly_summary.weekly_trans_count}, Amount={ws_weekly_summary.weekly_trans_amount}")

    except FileNotFoundError as fnfe:
        logger.error(f"Daily summary file not found: {DAILY_SUMMARY_FILE} - {fnfe}")
        raise
    except Exception as e:
        logger.error(f"Error summing week data: {e}")
        raise
    finally:
        logger.info("Sum week data completed")

