@dataclass
class WsDailySumRecC10:
    daily_month: int
    daily_trans_count: int
    daily_trans_amount: Decimal

def sum_month_data_C10(ws_monthly_summary: WsMonthlySummaryC10):
    """
    Sums the daily transaction data for the month
    Reads the DAILY_SUMMARY_FILE, filters records for the current month,
    and sums the transaction counts and amounts
    """
    logger.info("Starting sum month data")

    global WS_EOF_FLAG, WS_CURR_MONTH, DAILY_SUMMARY_FILE

    ws_monthly_summary.monthly_trans_count = 0
    ws_monthly_summary.monthly_trans_amount = Decimal("0")
    ws_monthly_summary.monthly_new_accounts = 0
    ws_monthly_summary.monthly_closed_accounts = 0
    WS_EOF_FLAG = 'N'

    try:
        with open(DAILY_SUMMARY_FILE, "r") as f:
            while WS_EOF_FLAG != 'Y':
                try:
                    line = f.readline().strip()
                    if not line:
                        WS_EOF_FLAG = 'Y'
                        logger.debug("End of daily summary file reached")
                        break

                    try:
                        daily_date, daily_trans_count, daily_trans_amount, daily_deposits, daily_withdrawals = line.strip().split(",")
                        daily_month = datetime.datetime.strptime(daily_date, "%Y%m%d").month

                        ws_daily_sum_rec = WsDailySumRecC10(
                            daily_month=daily_month,
                            daily_trans_count=int(daily_trans_count),
                            daily_trans_amount=Decimal(daily_trans_amount)
                        )
                    except ValueError as ve:
                        logger.warning(f"Skipping line due to invalid format in DAILY_SUMMARY_FILE: {line} - {ve}")
                        continue

                    if ws_daily_sum_rec.daily_month == WS_CURR_MONTH:
                        ws_monthly_summary.monthly_trans_count += ws_daily_sum_rec.daily_trans_count
                        ws_monthly_summary.monthly_trans_amount += ws_daily_sum_rec.daily_trans_amount

                    logger.debug(f"Read daily summary record: Month={ws_daily_sum_rec.daily_month}, Count={ws_daily_sum_rec.daily_trans_count}, Amount={ws_daily_sum_rec.daily_trans_amount}")
                except IOError as ioe:
                    logger.error(f"IOError while reading daily summary file: {ioe}")
                    WS_EOF_FLAG = 'Y'
                    raise

        WS_EOF_FLAG = 'N'

        logger.debug(f"Summed monthly data: Count={ws_monthly_summary.monthly_trans_count}, Amount={ws_monthly_summary.monthly_trans_amount}")

    except FileNotFoundError as fnfe:
        logger.error(f"Daily summary file not found: {DAILY_SUMMARY_FILE} - {fnfe}")
        raise
    except Exception as e:
        logger.error(f"Error summing month data: {e}")
        raise
    finally:
        logger.info("Sum month data completed")

