WS_TOTAL_ASSETS: Decimal = Decimal("1000000")
WS_NET_INCOME: Decimal = Decimal("50000")
WS_TOTAL_EQUITY: Decimal = Decimal("600000")
WS_INTEREST_EXPENSE: Decimal = Decimal("10000")
WS_INTEREST_INCOME: Decimal = Decimal("25000")
WS_EARNING_ASSETS: Decimal = Decimal("800000")
WS_ROA: Decimal = Decimal("0")
WS_ROE: Decimal = Decimal("0")
WS_NIM: Decimal = Decimal("0")

def calc_financial_kpi_C10():
    """
    Calculates financial KPIs such as ROA, ROE, and NIM
    Uses global variables for total assets, net income, total equity,
    interest expense, interest income, and earning assets to calculate the KPIs
    """
    logger.info("Starting financial KPI calculation")

    global WS_TOTAL_ASSETS, WS_NET_INCOME, WS_TOTAL_EQUITY, WS_INTEREST_EXPENSE, WS_INTEREST_INCOME, WS_EARNING_ASSETS
    global WS_ROA, WS_ROE, WS_NIM

    try:
        if WS_TOTAL_ASSETS > 0:
            WS_ROA = (WS_NET_INCOME / WS_TOTAL_ASSETS) * Decimal("100")
            logger.debug(f"Calculated ROA: {WS_ROA}")
        else:
            WS_ROA = Decimal("0")
            logger.warning("Total assets are zero, ROA cannot be calculated")

        if WS_TOTAL_EQUITY > 0:
            WS_ROE = (WS_NET_INCOME / WS_TOTAL_EQUITY) * Decimal("100")
            logger.debug(f"Calculated ROE: {WS_ROE}")
        else:
            WS_ROE = Decimal("0")
            logger.warning("Total equity is zero, ROE cannot be calculated")

        if WS_INTEREST_EXPENSE > 0:
            WS_NIM = ((WS_INTEREST_INCOME - WS_INTEREST_EXPENSE) / WS_EARNING_ASSETS) * Decimal("100")
            logger.debug(f"Calculated NIM: {WS_NIM}")
        else:
            WS_NIM = Decimal("0")
            logger.warning("Interest expense is zero, NIM cannot be calculated")

    except Exception as e:
        logger.error(f"Error calculating financial KPIs: {e}")
        raise
    finally:
        logger.info("Financial KPI calculation completed")

WS_ERROR_COUNT: int = 100
WS_TOTAL_TRANS_COUNT: int = 10000
WS_WITHIN_SLA_COUNT: int = 9500
WS_TOTAL_CASES: int = 10000
WS_FCR_COUNT: int = 8000
WS_TOTAL_CALLS: int = 10000
WS_ERROR_RATE: Decimal = Decimal("0")
WS_SLA_COMPLIANCE: Decimal = Decimal("0")
WS_FIRST_CALL_RESOLUTION: Decimal = Decimal("0")

def calc_operational_kpi_C10():
    """
    Calculates operational KPIs such as error rate, SLA compliance, and first call resolution
    Uses global variables for error count, total transaction count, within SLA count,
    total cases, FCR count, and total calls to calculate the KPIs
    """
    logger.info("Starting operational KPI calculation")

    global WS_ERROR_COUNT, WS_TOTAL_TRANS_COUNT, WS_WITHIN_SLA_COUNT, WS_TOTAL_CASES, WS_FCR_COUNT, WS_TOTAL_CALLS
    global WS_ERROR_RATE, WS_SLA_COMPLIANCE, WS_FIRST_CALL_RESOLUTION

    try:
        if WS_TOTAL_TRANS_COUNT > 0:
            WS_ERROR_RATE = (Decimal(str(WS_ERROR_COUNT)) / Decimal(str(WS_TOTAL_TRANS_COUNT))) * Decimal("100")
            logger.debug(f"Calculated Error Rate: {WS_ERROR_RATE}")
        else:
            WS_ERROR_RATE = Decimal("0")
            logger.warning("Total transaction count is zero, error rate cannot be calculated")

        WS_SLA_COMPLIANCE = (Decimal(str(WS_WITHIN_SLA_COUNT)) / Decimal(str(WS_TOTAL_CASES))) * Decimal("100")
        logger.debug(f"Calculated SLA Compliance: {WS_SLA_COMPLIANCE}")

        WS_FIRST_CALL_RESOLUTION = (Decimal(str(WS_FCR_COUNT)) / Decimal(str(WS_TOTAL_CALLS))) * Decimal("100")
        logger.debug(f"Calculated First Call Resolution: {WS_FIRST_CALL_RESOLUTION}")

    except Exception as e:
        logger.error(f"Error calculating operational KPIs: {e}")
        raise
    finally:
        logger.info("Operational KPI calculation completed")

WS_ACTIVE_CUSTOMERS: int = 1

import datetime

# Get logger
logger = logging.getLogger(__name__)

def express_or_standard_shipping_C11(
    ws_process_date: datetime.date
) -> Dict[str, Any]:
    """
    Determines shipping method and estimated delivery date
    This function evaluates a condition and sets the shipping method
    and estimated delivery date based on the outcome
    Args:
        ws_process_date: The date of order processing
    Returns:
        Dict[str, Any]: Dictionary containing the shipping method and
                         estimated delivery date
    """
    logger.info("Determining shipping method and delivery date")
    
    try:
        ship_method: str
        ship_est_delivery: int

        if ws_process_date.day <= 15: #Using the day of the date for the condition
            ship_method = 'EXPRESS'
            logger.debug(f"Shipping method set to {ship_method}")

            # Compute ship_est_delivery using integer representation of the date + 2
            ship_est_delivery = ws_process_date.toordinal() + 2
            logger.debug(f"Estimated delivery date set to {ship_est_delivery}")
        else:
            ship_method = 'STANDARD'
            logger.debug(f"Shipping method set to {ship_method}")

            # Compute ship_est_delivery using integer representation of the date + 7
            ship_est_delivery = ws_process_date.toordinal() + 7
            logger.debug(f"Estimated delivery date set to {ship_est_delivery}")

        # Simulate writing to a file
        ws_shipment_record = {"ship_method": ship_method, "ship_est_delivery": ship_est_delivery}
        logger.info("Writing shipment record")
        #write_file("shipment_record", ws_shipment_record) # Example call to external function
        
        return {"ship_method": ship_method, "ship_est_delivery": ship_est_delivery}
    except Exception as e:
        logger.error(f"Error determining shipping: {e}")
        raise

def card_blocking_C11(
    ws_block_reason: str,
    ws_process_date: datetime.date,
    card_record: Dict[str, Any]
) -> None:
    """
    Blocks a card, updates the record, and sends a notification
    This function sets the card status to 'B', updates the card record with
    the block reason and date, and sends a notification to the user
    Args:
        ws_block_reason: The reason for blocking the card
        ws_process_date: The date the card was blocked
        card_record: Dictionary containing the card record
    """
    logger.info("Blocking card and sending notification")
    
    try:
        # Set card status to blocked
        card_status = 'B'
        logger.debug(f"Card status set to {card_status}")

        # Update card record
        card_block_reason = ws_block_reason
        card_block_date = ws_process_date
        logger.debug(f"Card blocked due to {card_block_reason} on {card_block_date}")

        # Rewrite card record
        card_record["card_status"] = card_status
        card_record["card_block_reason"] = card_block_reason
        card_record["card_block_date"] = card_block_date
        #rewrite_file("card_record", card_record) # Example call to external function
        logger.debug("Card record updated and rewritten")

        # Create notification
        ws_notif_type = 'card_blocked'
        ws_notif_channel = 'SMS'
        ws_notif_body = f"Your card has been blocked: {ws_block_reason}"
        logger.debug(f"Notification type: {ws_notif_type}, channel: {ws_notif_channel}, body: {ws_notif_body}")

        # Send notification
        send_notification_C11(ws_notif_type, ws_notif_channel, ws_notif_body) # Calls 15000-send_notification
        
    except Exception as e:
        logger.error(f"Error blocking card: {e}")
        raise

