def validate_stop_request_C29100(
    ws_check_number: Decimal,
    ws_check_already_cleared: str
) -> Tuple[str, Optional[str]]:
    """
    Validates a stop payment request based on check number and clearance status
    This function checks if a check number is provided and if the check has already
    been cleared. It returns a validation flag and a rejection message if the
    request is invalid
    Args:
        ws_check_number: The check number to be stopped (PIC 9(8)). Must be non-zero
        ws_check_already_cleared: Flag indicating if the check is already cleared ('Y' or 'N')
    Returns:
        Tuple[str, Optional[str]]: A tuple containing the validation flag ('Y' or 'N') and an
                                  optional rejection message.  If validation fails, the flag is 'N' and
                                  a rejection message is provided. If validation succeeds, the flag is 'Y'
                                  and the message is None
    Raises:
        ValueError: If ws_check_already_cleared is not 'Y' or 'N'
    """
    logger.info("Validating stop payment request.")

    # Input validation
    if not isinstance(ws_check_number, Decimal):
        logger.error(f"Invalid type for ws_check_number: {type(ws_check_number)}")
        raise ValueError("ws_check_number must be a Decimal.")

    if ws_check_already_cleared not in ('Y', 'N'):
        logger.error(f"Invalid value for ws_check_already_cleared: {ws_check_already_cleared}")
        raise ValueError("ws_check_already_cleared must be 'Y' or 'N'.")

    try:
        ws_stop_valid: str = 'Y'
        ws_stop_reject: Optional[str] = None
        
        if ws_check_number == Decimal('0'):
            ws_stop_valid = 'N'
            ws_stop_reject = 'CHECK NUMBER REQUIRED'
            logger.debug("Check number is zero, setting ws_stop_valid to N and ws_stop_reject.")
        
        if ws_check_already_cleared == 'Y':
            ws_stop_valid = 'N'
            ws_stop_reject = 'CHECK ALREADY CLEARED'
            logger.debug("Check already cleared, setting ws_stop_valid to N and ws_stop_reject.")
        
        logger.info(f"Stop payment request validated: Valid={ws_stop_valid}, RejectMessage={ws_stop_reject}")
        return ws_stop_valid, ws_stop_reject
    
    except Exception as e:
        logger.error(f"Error during stop payment request validation: {e}")
        raise

def create_stop_order_C29200(
    acct_id: str,
    ws_check_number: Decimal,
    ws_check_amount: Decimal,
    ws_payee_name: str,
    ws_process_date: int
) -> None:
    """
    Creates a stop payment order record
    This function initializes a stop payment record with the provided account
    information, check details, and processing date. It calculates the expiry date
    and sets the initial status to 'A' (Active). The record is then written to
    the stop_record file
    Args:
        acct_id: The account ID (PIC X(10))
        ws_check_number: The check number (PIC 9(8))
        ws_check_amount: The check amount (PIC 9(8)V99)
        ws_payee_name: The payee name (PIC X(30))
        ws_process_date: The processing date in YYYYMMDD format (PIC 9(8))
    Raises:
        ValueError: If any of the input parameters are invalid
        IOError: If there is an error writing to the stop_record file
    """
    logger.info("Creating stop payment order record.")

    # Input validation
    if not isinstance(acct_id, str) or len(acct_id) > 10:
        logger.error(f"Invalid account ID: {acct_id}")
        raise ValueError("Invalid account ID. Must be a string of length <= 10.")
    
    if not isinstance(ws_check_number, Decimal):
        logger.error(f"Invalid check number: {ws_check_number}")
        raise ValueError("Invalid check number. Must be a Decimal.")

    if not isinstance(ws_check_amount, Decimal):
        logger.error(f"Invalid check amount: {ws_check_amount}")
        raise ValueError("Invalid check amount. Must be a Decimal.")

    if not isinstance(ws_payee_name, str) or len(ws_payee_name) > 30:
        logger.error(f"Invalid payee name: {ws_payee_name}")
        raise ValueError("Invalid payee name. Must be a string of length <= 30.")

    if not isinstance(ws_process_date, int):
        logger.error(f"Invalid process date: {ws_process_date}")
        raise ValueError("Invalid process date. Must be an integer.")
    
    try:
        # Initialize ws_stop_record (assuming it's a dictionary)'
        ws_stop_record: Dict[str, Any] = {}

        # Move data to the record fields
        stop_account: str = acct_id
        stop_check_number: Decimal = ws_check_number
        stop_amount: Decimal = ws_check_amount
        stop_payee: str = ws_payee_name
        stop_effective_date: int = ws_process_date
        
        # Calculate expiry date
        stop_expiry_date: int = ws_process_date + 180 #FUNCTION integer_of_date(ws_process_date) + 180
        
        stop_status: str = 'A' # Active status
        
        # Populate the ws_stop_record
        ws_stop_record['stop_account'] = stop_account
        ws_stop_record['stop_check_number'] = stop_check_number
        ws_stop_record['stop_amount'] = stop_amount
        ws_stop_record['stop_payee'] = stop_payee
        ws_stop_record['stop_effective_date'] = stop_effective_date
        ws_stop_record['stop_expiry_date'] = stop_expiry_date
        ws_stop_record['stop_status'] = stop_status
        
        # Write stop_record from ws_stop_record (assuming a write_file function)
        write_file("stop_record", ws_stop_record)
        logger.debug(f"Stop payment order record written: {ws_stop_record}")
        
    except Exception as e:
        logger.error(f"Error creating stop payment order: {e}")
        raise

def apply_stop_fee_C29300(
    ws_stop_payment_fee: Decimal,
    ws_account_balance: Decimal,
    ws_check_number: Decimal
) -> None:
    """
    Applies a stop payment fee to the account and sends a notification
    This function subtracts the stop payment fee from the account balance, updates
    the account record, and sends a notification to the customer
    Args:
        ws_stop_payment_fee: The stop payment fee amount (PIC 9(5)V99)
        ws_account_balance: The account balance (PIC 9(9)V99)
        ws_check_number: The check number that the stop payment was placed on
    Raises:
        ValueError: If any of the input parameters are invalid
        Exception: If there is an error updating the account or sending the notification
    """
    logger.info("Applying stop payment fee and sending notification.")

    # Input validation
    if not isinstance(ws_stop_payment_fee, Decimal):
        logger.error(f"Invalid stop payment fee: {ws_stop_payment_fee}")
        raise ValueError("Invalid stop payment fee. Must be a Decimal.")

    if not isinstance(ws_account_balance, Decimal):
        logger.error(f"Invalid account balance: {ws_account_balance}")
        raise ValueError("Invalid account balance. Must be a Decimal.")
    
    try:
        # Local variables (COBOL Working Storage)
        ws_notif_type: str = ''
        ws_notif_channel: str = ''
        ws_notif_subject: str = ''

        # Subtract the stop payment fee from the account balance
        new_account_balance: Decimal = ws_account_balance - ws_stop_payment_fee
        logger.debug(f"New account balance after fee deduction: {new_account_balance}")
        
        # Update the account (assuming update_account function exists)
        update_account_C2350(new_account_balance)  # PERFORM 2350-update_account

        # Set notification parameters
        ws_notif_type = 'stop_payment'
        ws_notif_channel = 'EMAIL'

        # Build notification subject
        ws_notif_subject = f"Stop payment placed on check # {ws_check_number}" #STRING 'Stop payment placed on check #' DELIMITED SIZE ws_check_number DELIMITED SIZE

        # Send notification (assuming send_notification function exists)
        send_notification_C15000(ws_notif_type, ws_notif_channel, ws_notif_subject)  # PERFORM 15000-send_notification
        
        logger.info("Stop payment fee applied and notification sent.")
    
    except Exception as e:
        logger.error(f"Error applying stop payment fee: {e}")
        raise

