def check_availability_C30110(
    ws_total_boxes: int,
    ws_requested_size: str,
    box_status: List[str],
    box_size: List[str]
) -> Tuple[str, Optional[int]]:
    """
    Checks the availability of safe deposit boxes
    This function iterates through the available boxes, checking the status and size to determine
    if a suitable box is available
    Args:
        ws_total_boxes: Total number of boxes
        ws_requested_size: The requested box size
        box_status: A list of box statuses (e.g., 'A' for available)
        box_size: A list of box sizes corresponding to the box statuses
    Returns:
        Tuple[str, Optional[int]]: A tuple indicating box availability and assigned box index
                                'Y' and the assigned box index, or 'N' and None
    Raises:
        ValueError: If ws_total_boxes is not a positive integer
    """

    logger.info("Checking Box Availability.")

    if not isinstance(ws_total_boxes, int) or ws_total_boxes <= 0:
        logger.error(f"Invalid value for ws_total_boxes: {ws_total_boxes}")
        raise ValueError("ws_total_boxes must be a positive integer.")

    try:
        ws_box_available: str = 'N'
        ws_assigned_box: Optional[int] = None

        for ws_box_idx in range(1, ws_total_boxes + 1):
            if box_status[ws_box_idx - 1] == 'A':
                if box_size[ws_box_idx - 1] == ws_requested_size:
                    ws_box_available = 'Y'
                    ws_assigned_box = ws_box_idx
                    logger.debug(f"Found available box at index: {ws_assigned_box}")
                    break  # EXIT PERFORM

        logger.info(f"Box Availability Check completed. Available: {ws_box_available}, Assigned Box: {ws_assigned_box}")
        return ws_box_available, ws_assigned_box

    except Exception as e:
        logger.error(f"An error occurred during box availability check: {e}")
        raise

def assign_box_C30120(
    ws_assigned_box: int,
    ws_customer_id: str,
    ws_process_date: int,
    box_status: List[str],
    box_renter: List[str],
    box_rental_date: List[int]
) -> None:
    """
    Assigns a safe deposit box to a customer
    This function updates the box status, renter, and rental date for the assigned box
    Args:
        ws_assigned_box: The index of the box to be assigned
        ws_customer_id: The customer ID of the renter
        ws_process_date: The process date (YYYYMMDD)
        box_status: A list of box statuses (e.g., 'R' for rented)
        box_renter: A list of customer IDs corresponding to each box
        box_rental_date: A list of rental dates corresponding to each box
    Raises:
        ValueError: If ws_assigned_box is not a positive integer or ws_customer_id is not a string
    """
    logger.info("Assigning Box to Customer.")

    if not isinstance(ws_assigned_box, int) or ws_assigned_box <= 0:
        logger.error(f"Invalid value for ws_assigned_box: {ws_assigned_box}")
        raise ValueError("ws_assigned_box must be a positive integer.")

    if not isinstance(ws_customer_id, str):
        logger.error(f"Invalid value for ws_customer_id: {ws_customer_id}")
        raise ValueError("ws_customer_id must be a string.")

    try:
        box_status[ws_assigned_box - 1] = 'R'  # 'R' for rented
        box_renter[ws_assigned_box - 1] = ws_customer_id
        box_rental_date[ws_assigned_box - 1] = ws_process_date

        logger.info(f"Box {ws_assigned_box} assigned to customer {ws_customer_id}.")

    except Exception as e:
        logger.error(f"An error occurred during box assignment: {e}")
        raise

def create_rental_agreement_C30130(
    ws_assigned_box: int,
    ws_customer_id: str,
    ws_process_date: int,
    ws_requested_size: str,
    ws_box_size_fee: Dict[str, Decimal]
) -> None:
    """
    Creates a rental agreement record for a safe deposit box
    This function initializes a rental agreement record with the provided box number, customer ID,
    start date, and annual fee. The record is then written to the rental_record file
    Args:
        ws_assigned_box: The assigned box number
        ws_customer_id: The customer ID of the renter
        ws_process_date: The process date (YYYYMMDD)
        ws_requested_size: The size of the requested box
        ws_box_size_fee: A dictionary mapping box sizes to annual fees
    Raises:
        ValueError: If ws_assigned_box is not a positive integer, ws_customer_id is not a string,
                    or ws_requested_size is not in ws_box_size_fee
        IOError: If there is an error writing to the rental_record file
    """
    logger.info("Creating Rental Agreement Record.")

    if not isinstance(ws_assigned_box, int) or ws_assigned_box <= 0:
        logger.error(f"Invalid value for ws_assigned_box: {ws_assigned_box}")
        raise ValueError("ws_assigned_box must be a positive integer.")

    if not isinstance(ws_customer_id, str):
        logger.error(f"Invalid value for ws_customer_id: {ws_customer_id}")
        raise ValueError("ws_customer_id must be a string.")

    if ws_requested_size not in ws_box_size_fee:
        logger.error(f"Invalid value for ws_requested_size: {ws_requested_size}")
        raise ValueError("ws_requested_size is not a valid box size.")

    try:
        # Initialize ws_rental_agreement
        ws_rental_agreement: Dict[str, Any] = {}

        # Move data to the record fields
        rental_box_number: int = ws_assigned_box
        rental_customer: str = ws_customer_id
        rental_start_date: int = ws_process_date
        rental_annual_fee: Decimal = ws_box_size_fee[ws_requested_size]

        # Populate ws_rental_agreement
        ws_rental_agreement['rental_box_number'] = rental_box_number
        ws_rental_agreement['rental_customer'] = rental_customer
        ws_rental_agreement['rental_start_date'] = rental_start_date
        ws_rental_agreement['rental_annual_fee'] = rental_annual_fee

        # Write rental_record from ws_rental_agreement
        write_file("rental_record", ws_rental_agreement)

        logger.info("Rental Agreement Record created successfully.")

    except Exception as e:
        logger.error(f"An error occurred during rental agreement creation: {e}")
        raise

def box_access_C30200(
    ws_access_request: str,
    ws_box_number: int,
    ws_customer_id: str,
    ws_id_verified: str,
    ws_key_verified: str,
    box_renter: List[str],
    ws_process_date: int,
    access_log_record: str
) -> None:
    """
    Handles safe deposit box access requests
    This function checks if an access request is present, and if so, verifies the renter, logs the access,
    and escorts the renter to the vault
    Args:
        ws_access_request: 'Y' if there is an access request, 'N' otherwise
        ws_box_number: The number of the box to access
        ws_customer_id: The customer ID of the renter
        ws_id_verified: 'Y' if the ID is verified, 'N' otherwise
        ws_key_verified: 'Y' if the key is verified, 'N' otherwise
        box_renter: A list of renters of each box
        ws_process_date: Current process date
        access_log_record: The access log file
    Raises:
        ValueError: If ws_access_request, ws_id_verified, or ws_key_verified are not 'Y' or 'N'
    """
    logger.info("Processing Box Access Request.")

    if ws_access_request not in ('Y', 'N'):
        logger.error(f"Invalid value for ws_access_request: {ws_access_request}")
        raise ValueError("ws_access_request must be 'Y' or 'N'.")

    if ws_id_verified not in ('Y', 'N'):
        logger.error(f"Invalid value for ws_id_verified: {ws_id_verified}")
        raise ValueError("ws_id_verified must be 'Y' or 'N'.")

    if ws_key_verified not in ('Y', 'N'):
        logger.error(f"Invalid value for ws_key_verified: {ws_key_verified}")
        raise ValueError("ws_key_verified must be 'Y' or 'N'.")

    try:
        if ws_access_request == 'Y':
            renter_verified_C30210(ws_box_number, ws_customer_id, ws_id_verified, ws_key_verified, box_renter)
            if ws_renter_verified == 'Y':
                log_access_C30220(ws_box_number, ws_customer_id, ws_process_date, access_log_record)
                escort_to_vault_C30230()

        logger.info("Box Access Request processed.")

    except Exception as e:
        logger.error(f"An error occurred during box access processing: {e}")
        raise

def renter_verified_C30210(
    ws_box_number: int,
    ws_customer_id: str,
    ws_id_verified: str,
    ws_key_verified: str,
    box_renter: List[str],
) -> str:
    """
    Verifies the renter of a safe deposit box
    This function checks if the customer ID matches the renter of the box and if the ID and key are verified
    Args:
        ws_box_number: The number of the box to access
        ws_customer_id: The customer ID of the renter
        ws_id_verified: 'Y' if the ID is verified, 'N' otherwise
        ws_key_verified: 'Y' if the key is verified, 'N' otherwise
        box_renter: A list of renters of each box
    Returns:
        str: 'Y' if the renter is verified, 'N' otherwise
    Raises:
        ValueError: If ws_id_verified or ws_key_verified are not 'Y' or 'N'
    """
    logger.info("Verifying Renter.")

    if ws_id_verified not in ('Y', 'N'):
        logger.error(f"Invalid value for ws_id_verified: {ws_id_verified}")
        raise ValueError("ws_id_verified must be 'Y' or 'N'.")

    if ws_key_verified not in ('Y', 'N'):
        logger.error(f"Invalid value for ws_key_verified: {ws_key_verified}")
        raise ValueError("ws_key_verified must be 'Y' or 'N'.")

    try:
        ws_renter_verified: str = 'N'

        if box_renter[ws_box_number - 1] == ws_customer_id:
            if ws_id_verified == 'Y':
                if ws_key_verified == 'Y':
                    ws_renter_verified = 'Y'

        logger.info(f"Renter Verification completed. Verified: {ws_renter_verified}")
        return ws_renter_verified

    except Exception as e:
        logger.error(f"An error occurred during renter verification: {e}")
        raise

