def box_drilling_C30300(
    ws_drilling_request: str,
    ws_box_number: int,
    ws_rent_delinquent_months: int,
    ws_court_order: str,
    ws_deceased_renter: str,
    ws_executor_verified: str,
    ws_drilling_reason: str,
    ws_process_date: int,
    drilling_record: str,
    ws_notif_channel: str,
    ws_notif_subject: str
) -> None:
    """
    Handles safe deposit box drilling requests
    This function checks if a drilling request is present, and if so, validates drilling authorization,
    schedules the drilling, and notifies the renter
    Args:
        ws_drilling_request: 'Y' if there is a drilling request, 'N' otherwise
        ws_box_number: The number of the box to be drilled
        ws_rent_delinquent_months: Number of months the rent is delinquent
        ws_court_order: 'Y' if there is a court order, 'N' otherwise
        ws_deceased_renter: 'Y' if the renter is deceased, 'N' otherwise
        ws_executor_verified: 'Y' if the executor is verified, 'N' otherwise
        ws_drilling_reason: The reason for the drilling
        ws_process_date: the process date
        drilling_record: The drilling log file
        ws_notif_channel: notification channel
        ws_notif_subject: Notification subject
    Raises:
        ValueError: If ws_drilling_request, ws_court_order, ws_deceased_renter, or ws_executor_verified are not 'Y' or 'N'
    """
    logger.info("Processing Box Drilling Request.")

    if ws_drilling_request not in ('Y', 'N'):
        logger.error(f"Invalid value for ws_drilling_request: {ws_drilling_request}")
        raise ValueError("ws_drilling_request must be 'Y' or 'N'.")

    if ws_court_order not in ('Y', 'N'):
        logger.error(f"Invalid value for ws_court_order: {ws_court_order}")
        raise ValueError("ws_court_order must be 'Y' or 'N'.")

    if ws_deceased_renter not in ('Y', 'N'):
        logger.error(f"Invalid value for ws_deceased_renter: {ws_deceased_renter}")
        raise ValueError("ws_deceased_renter must be 'Y' or 'N'.")

    if ws_executor_verified not in ('Y', 'N'):
        logger.error(f"Invalid value for ws_executor_verified: {ws_executor_verified}")
        raise ValueError("ws_executor_verified must be 'Y' or 'N'.")

    try:
        if ws_drilling_request == 'Y':
            validate_drilling_auth_C30310(ws_rent_delinquent_months, ws_court_order, ws_deceased_renter, ws_executor_verified)
            if ws_drilling_authorized == 'Y':
                schedule_drilling_C30320(ws_box_number, ws_drilling_reason, ws_process_date, drilling_record)
                notify_renter_C30330(ws_notif_channel, ws_notif_subject)

        logger.info("Box Drilling Request processed.")

    except Exception as e:
        logger.error(f"An error occurred during box drilling processing: {e}")
        raise

def validate_drilling_auth_C30310(
    ws_rent_delinquent_months: int,
    ws_court_order: str,
    ws_deceased_renter: str,
    ws_executor_verified: str
) -> str:
    """
    Validates the authorization for drilling a safe deposit box
    This function checks if the rent is delinquent for 12 months or more, if there is a court order,
    or if the renter is deceased and the executor is verified
    Args:
        ws_rent_delinquent_months: Number of months the rent is delinquent
        ws_court_order: 'Y' if there is a court order, 'N' otherwise
        ws_deceased_renter: 'Y' if the renter is deceased, 'N' otherwise
        ws_executor_verified: 'Y' if the executor is verified, 'N' otherwise
    Returns:
        str: 'Y' if the drilling is authorized, 'N' otherwise
    Raises:
        ValueError: If ws_court_order, ws_deceased_renter, or ws_executor_verified are not 'Y' or 'N'
    """
    logger.info("Validating Drilling Authorization.")

    if ws_court_order not in ('Y', 'N'):
        logger.error(f"Invalid value for ws_court_order: {ws_court_order}")
        raise ValueError("ws_court_order must be 'Y' or 'N'.")

    if ws_deceased_renter not in ('Y', 'N'):
        logger.error(f"Invalid value for ws_deceased_renter: {ws_deceased_renter}")
        raise ValueError("ws_deceased_renter must be 'Y' or 'N'.")

    if ws_executor_verified not in ('Y', 'N'):
        logger.error(f"Invalid value for ws_executor_verified: {ws_executor_verified}")
        raise ValueError("ws_executor_verified must be 'Y' or 'N'.")

    try:
        ws_drilling_authorized: str = 'N'

        if ws_rent_delinquent_months >= 12:
            ws_drilling_authorized = 'Y'
        if ws_court_order == 'Y':
            ws_drilling_authorized = 'Y'
        if ws_deceased_renter == 'Y':
            if ws_executor_verified == 'Y':
                ws_drilling_authorized = 'Y'

        logger.info(f"Drilling Authorization Validation completed. Authorized: {ws_drilling_authorized}")
        return ws_drilling_authorized

    except Exception as e:
        logger.error(f"An error occurred during drilling authorization validation: {e}")
        raise

