def run_baseline_C14() -> Dict[str, Any]:
    """
    Runs the baseline stress test scenario
    This function sets parameters for the baseline scenario, including rate shock,
    GDP change, unemployment rate, and housing decline, then calls the stress
    impact calculation function
    Args:
        None
    Returns:
        Dict[str, Any]: A dictionary containing the stress test parameters and results
    Raises:
        Exception: If any error occurs during the baseline scenario
    """

    logger.info("Running Baseline Stress Test.")

    try:
        # Set baseline scenario parameters
        ws_scenario_name = 'BASELINE'
        ws_rate_shock = Decimal('0.00')
        ws_gdp_change = Decimal('2.50')
        ws_unemployment_rate = Decimal('4.00')
        ws_housing_decline = Decimal('0.00')

        logger.debug(f"Scenario: {ws_scenario_name}, Rate Shock: {ws_rate_shock}, GDP Change: {ws_gdp_change}, Unemployment Rate: {ws_unemployment_rate}, Housing Decline: {ws_housing_decline}")

        # Calculate stress impact
        stress_impact = calculate_stress_impact_C14(
            ws_rate_shock, ws_gdp_change, ws_unemployment_rate, ws_housing_decline
        )

        # Store parameters and impact
        baseline_results = {
            "scenario_name": ws_scenario_name,
            "rate_shock": ws_rate_shock,
            "gdp_change": ws_gdp_change,
            "unemployment_rate": ws_unemployment_rate,
            "housing_decline": ws_housing_decline,
            "stress_impact": stress_impact
        }

        logger.info("Baseline Stress Test completed successfully.")
        return baseline_results

    except Exception as e:
        logger.error(f"Error occurred during Baseline Stress Test: {e}")
        raise

