        # Move ws_recon_diff to recon_exc_diff
        ws_recon_exception.recon_exc_diff = ws_recon_diff
        logger.debug(f"Moved ws_recon_diff ({ws_recon_diff}) to ws_recon_exception.recon_exc_diff")
        
        # Move FUNCTION current_date to recon_exc_date
        ws_recon_exception.recon_exc_date = str(datetime.date.today())
        logger.debug(f"Moved current date to ws_recon_exception.recon_exc_date")
        
        # Prepare the record string for writing to file
        recon_exception_record = (
            f"{ws_recon_exception.recon_exc_account:<20}"
            f"{str(ws_recon_exception.recon_exc_diff):<15}"
            f"{ws_recon_exception.recon_exc_date:<10}"
        )
        
        # Write recon_exception_record from ws_recon_exception
        write_file(recon_exception_record_file, recon_exception_record)
