def perform_37300_intercompany_recon_C15(
    intercompany_file: str,
    ws_ic_array: List[Dict[str, Any]],
    ic_diff_record_file: str,
    ws_eof_flag: str = 'N',
) -> None:
    """
    Performs intercompany reconciliation
    Calls sub-procedures to load intercompany balances, match pairs, and report differences
    Args:
        intercompany_file: Path to the intercompany file
        ws_ic_array: Array to hold the intercompany balances
        ic_diff_record_file: Path to the intercompany difference record file
        ws_eof_flag: End of file flag
    Returns:
        None
    
    Raises:
        Exception: If any of the sub-procedures fail
    """
    logger.info("Executing 37300-intercompany_recon")
    
    try:
        # Perform 37310-load_ic_balances
        perform_37310_load_ic_balances_C15(intercompany_file, ws_ic_array)
        
        # Perform 37320-match_ic_pairs
        perform_37320_match_ic_pairs_C15(ws_ic_array, ic_diff_record_file)
        
        # Perform 37330-report_ic_differences
        perform_37330_report_ic_differences_C15()
        
    except Exception as e:
        logger.error(f"Error in 37300-intercompany_recon: {e}")
        raise

def perform_37310_load_ic_balances_C15(
    intercompany_file: str,
    ws_ic_array: List[Dict[str, Any]],
    ws_eof_flag: str = 'N',
) -> None:
    """
    Loads intercompany balances from a file into an array
    Reads the intercompany_file record by record until the end-of-file is reached
    For each record, it adds it to the ws_ic_array
    Args:
        intercompany_file: Path to the intercompany file
        ws_ic_array: Array to hold the intercompany balances
        ws_eof_flag: End of file flag
    Returns:
        None
    
    Raises:
        Exception: If there is an error reading the intercompany_file
    """
    logger.info("Executing 37310-load_ic_balances")
    
    try:
        # Move ZEROES to ws_ic_count
        ws_ic_count = 0
        
        # Move 'N' to ws_eof_flag
        ws_eof_flag = 'N'
        
        # Perform UNTIL ws_eof_flag = 'Y'
        while ws_eof_flag != 'Y':
            # READ intercompany_file INTO ws_ic_balance
            ic_balance = read_file(intercompany_file)
            
            if ic_balance is None:
                # AT END
                # MOVE 'Y' TO ws_eof_flag
                ws_eof_flag = 'Y'
                logger.info("End of file reached for intercompany_file")
            else:
                # NOT AT END
                # ADD 1 TO ws_ic_count
                ws_ic_count += 1
                
                # MOVE ws_ic_balance to ws_ic_array(ws_ic_count)
                # Assuming ws_ic_balance is a string, convert to a dictionary (mock)
                ws_ic_balance_dict = {"balance": ic_balance}
                
                if ws_ic_count <= len(ws_ic_array):
                    ws_ic_array[ws_ic_count - 1] = ws_ic_balance_dict
                    logger.debug(f"Loaded intercompany balance: {ws_ic_balance_dict} into ws_ic_array at index {ws_ic_count}")
                else:
                    logger.warning(f"ws_ic_count ({ws_ic_count}) exceeds ws_ic_array size ({len(ws_ic_array)}). Balance not added.")
        
        # MOVE 'N' TO ws_eof_flag (resetting after loop)
        ws_eof_flag = 'N'
    
    except Exception as e:
        logger.error(f"Error in 37310-load_ic_balances: {e}")
        raise

def perform_37320_match_ic_pairs_C15(
    ws_ic_array: List[Dict[str, Any]],
    ic_diff_record_file: str,
) -> None:
    """COBOL logic"""
    logger.info("Executing 37320-match_ic_pairs")
    
    try:
        # PERFORM VARYING ws_ic_idx FROM 1 BY 1 UNTIL ws_ic_idx > ws_ic_count
        ws_ic_count = len(ws_ic_array)
        for ws_ic_idx in range(1, ws_ic_count + 1):
            # Perform 37325-find_ic_counterpart
            perform_37325_find_ic_counterpart_C15(ws_ic_idx, ws_ic_array, ic_diff_record_file)
    
    except Exception as e:
        logger.error(f"Error in 37320-match_ic_pairs: {e}")
        raise

def perform_37325_find_ic_counterpart_C15(
    ws_ic_idx: int,
    ws_ic_array: List[Dict[str, Any]],
    ic_diff_record_file: str,
) -> None:
    """COBOL logic"""
    logger.info("Executing 37325-find_ic_counterpart")
    
    try:
        # Assuming structure of entries in ws_ic_array is as follows:
        # { 'ic_from_entity': 'A', 'ic_to_entity': 'B', 'ic_amount': Decimal('100') }
        
        # Get the current IC entry
        current_ic_entry = ws_ic_array[ws_ic_idx - 1] if ws_ic_idx <= len(ws_ic_array) else None
        
        if current_ic_entry is None:
            logger.warning(f"No IC entry found at index {ws_ic_idx}. Skipping.")
            return None
        # MOVE ic_from_entity(ws_ic_idx) TO ws_search_from
        ws_search_from = current_ic_entry.get('ic_from_entity', '')
        
        # MOVE ic_to_entity(ws_ic_idx) TO ws_search_to
        ws_search_to = current_ic_entry.get('ic_to_entity', '')
        
        # PERFORM VARYING ws_ic_idx2 FROM 1 BY 1 UNTIL ws_ic_idx2 > ws_ic_count
        ws_ic_count = len(ws_ic_array)
        for ws_ic_idx2 in range(1, ws_ic_count + 1):
            # Skip comparing the same entry to itself
            if ws_ic_idx == ws_ic_idx2:
                continue
            
            # Get the potential counterpart IC entry
            counterpart_ic_entry = ws_ic_array[ws_ic_idx2 - 1] if ws_ic_idx2 <= len(ws_ic_array) else None
            
            if counterpart_ic_entry is None:
                continue
            
            # IF ic_from_entity(ws_ic_idx2) = ws_search_to
            if counterpart_ic_entry.get('ic_from_entity', '') == ws_search_to:
                # IF ic_to_entity(ws_ic_idx2) = ws_search_from
                if counterpart_ic_entry.get('ic_to_entity', '') == ws_search_from:
                    # COMPUTE ws_ic_diff = ic_amount(ws_ic_idx) + ic_amount(ws_ic_idx2)
                    ic_amount1 = current_ic_entry.get('ic_amount', Decimal('0'))
                    ic_amount2 = counterpart_ic_entry.get('ic_amount', Decimal('0'))
                    ws_ic_diff = Decimal(str(ic_amount1)) + Decimal(str(ic_amount2))
                    
                    # IF ws_ic_diff NOT  = None  # TODO: was ZEROES
                    if ws_ic_diff != Decimal('0'):
                        # PERFORM 37326-log_ic_diff
                        perform_37326_log_ic_diff_C15(ws_search_from, ws_search_to, ws_ic_diff, ic_diff_record_file)
                    
                    # EXIT PERFORM (break the loop)
                    break
    
    except Exception as e:
        logger.error(f"Error in 37325-find_ic_counterpart: {e}")
        raise

